<?php require_once 'bootstrap.php';$error='';if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$email=strtolower(trim($_POST['email']??''));$pass=$_POST['password']??'';$s=db()->prepare('SELECT id,password_hash FROM users WHERE email=?');$s->execute([$email]);$u=$s->fetch();if($u&&password_verify($pass,$u['password_hash'])){session_regenerate_id(true);$_SESSION['user_id']=$u['id'];header('Location: account.php');exit;}else{$error='Email or password is incorrect.';}}$pageTitle='Log In | PC World Geek';require 'header.php';?><main class="page"><div class="wrap narrow"><span class="eyebrow">CUSTOMER ACCOUNT</span><h1>Welcome back.</h1><?php if($error):?><div class="notice"><?=e($error)?></div><?php endif;?><form class="booking-form" method="post"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><label>Email<input required type="email" name="email" autocomplete="email"></label><label>Password<input required type="password" name="password" autocomplete="current-password"></label><button class="btn primary">Log In →</button></form><p>New customer? <a class="arrowlink" href="register.php">Create an account</a></p></div></main><?php require 'footer.php';?>